import json, time, uuid, pathlib

class Tracer:
    def __init__(self, p={{trace_path}}):
        self.p = pathlib.Path(p); self.run = str(uuid.uuid4())
    def event(self, kind, **data):
        rec = {"run": self.run, "ts": time.time(), "kind": kind, **data}
        with self.p.open("a") as f: f.write(json.dumps(rec) + "\n")
